public class TryCatchFinallyDemo {
    public static int computeWithFinally(int divisor) {
        System.out.println("\n--- Executing computeWithFinally(" + divisor + ") ---");
        try {
            System.out.println("1. Entering try block");
            int result = 100 / divisor;
            System.out.println("2. Division success: " + result);
            return result; // Pauses here to run finally!
        } catch (ArithmeticException e) {
            System.out.println("3. Caught ArithmeticException in catch block");
            return -1;
        } finally {
            System.out.println("4. FINALLY block executed! (Cleanup guaranteed)");
        }
    }

    public static void main(String[] args) {
        // Scenario 1: Normal flow (divisor = 4)
        int normalResult = computeWithFinally(4);
        System.out.println("Final return value: " + normalResult);

        // Scenario 2: Exception flow (divisor = 0)
        int errorResult = computeWithFinally(0);
        System.out.println("Final return value: " + errorResult);
    }
}

